SELECT  FROM coal_washing_production
WHERE production_date = #{param1} AND unit_code = #{param2}
LIMIT 1

SELECT 
FROM coal_washing_production t


        AND t.production_date = #{productionDate}


        AND t.unit_code = #{unitCode}


        AND t.unit_name LIKE CONCAT('%', #{unitName}, '%')


        AND t.mine_category = #{mineCategory}


        AND t.user_id = #{userId}


        AND t.is_deleted = #{isDeleted}


ORDER BY t.production_date DESC, t.unit_code ASC
